[38.607844,-2.841315],[38.607958,-2.841355],[38.607997,-2.841358],[38.60804,-2.84137],[38.608159,-2.84139],[38.608272,-2.841434],[38.608348,-2.84146],[38.608446,-2.841483],[38.60846,-2.841477],[38.608594,-2.841542],[38.608714,-2.841655],[38.60874,-2.841656],[38.608936,-2.841624],[38.609075,-2.841638],[38.609249,-2.841645],[38.609263,-2.841654],[38.609375,-2.841696],[38.609493,-2.841725],[38.609648,-2.841686],[38.60984,-2.841611],[38.609854,-2.841582],[38.609894,-2.841566],[38.609924,-2.841516],[38.609936,-2.841461]]}]'::jsonb;
  v_source jsonb;
  v_route record;
  v_points jsonb;
  v_segments jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_id text;
  v_slug text;
begin
  for v_source in select value from jsonb_array_elements(v_sources) as x(value) loop
    v_id := v_source->>'route_id';
    v_slug := v_source->>'slug';
    select h.id,h.distance_km,h.latitude,h.longitude,t.status
      into v_route
      from public.hiking_routes h
      left join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_id and h.source='openstreetmap'
        and h.official_url='https://www.senderosdecastillalamancha.org/sendero/' || v_slug
        and exists (select 1 from public.hiking_route_regions m
          where m.route_id=h.id and m.published);
    if not found or v_route.status='ready' then
      continue;
    end if;
    with points as (
      select ordinality as idx, (point->>0)::double precision as lat,
        (point->>1)::double precision as lon
      from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point, ordinality)
    ), steps as (
      select idx,lat,lon,lag(lat) over (order by idx) as prev_lat,
        lag(lon) over (order by idx) as prev_lon from points
    ), distances as (
      select case when prev_lat is null then 0 else 6371 * 2 * asin(
        sqrt(least(1, power(sin(radians(lat-prev_lat)/2),2) +
          cos(radians(prev_lat))*cos(radians(lat))*
          power(sin(radians(lon-prev_lon)/2),2)))) end as step_km,
        6371 * 2 * asin(sqrt(least(1,
          power(sin(radians(lat-v_route.latitude)/2),2) +
          cos(radians(v_route.latitude))*cos(radians(lat))*
          power(sin(radians(lon-v_route.longitude)/2),2)))) as center_km,
        (lat between 27 and 45 and lon between -19 and 5) as valid
      from steps
    )
    select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter (where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;
    if v_count <> (v_source->>'expected_points')::integer
      or v_invalid > 0 or v_count < 100
      or v_length_km <= 0
      or abs(v_length_km / v_route.distance_km - 1) > 0.12
      or v_max_gap_km > 0.5 or v_center_gap_km > 1.2 then
      raise exception 'Official track validation failed for %: %, %, %, %, %',
        v_id,v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid;
    end if;
    select jsonb_agg(jsonb_build_object('lat',(point->>0)::double precision,
        'lon',(point->>1)::double precision) order by ordinality)
      into v_points
      from jsonb_array_elements(v_source->'coords')
        with ordinality as p(point, ordinality);
    v_segments := jsonb_build_array(v_points);
    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (v_id,'ready',v_segments,now(),true,
      'Federación de Deportes de Montaña de Castilla-La Mancha',
      'https://www.senderosdecastillalamancha.org/resources/senderos/'
        || v_slug || '/1/track.gpx',true)
    on conflict (route_id) do update set
      status=excluded.status,segments=excluded.segments,
      checked_at=excluded.checked_at,continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,official=true;
    update public.hiking_routes set trace_available=true,published=true
      where id=v_id;
  end loop;
end
